import Autocomplete, {
  type AutocompleteProps,
  type AutocompleteRenderInputParams,
} from '@mui/material/Autocomplete';
import Box from '@mui/material/Box';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import IconButton, { type IconButtonProps } from '@mui/material/IconButton';
import Portal from '@mui/material/Portal';
import { mergeSlotProps } from '@mui/material/utils';
import { composeRefs } from '@radix-ui/react-compose-refs';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useRef,
  type ReactNode,
  type Ref,
  type RefObject,
} from 'react';
import { SvChip } from '../sv-chip/sv-chip';
import { SvField, type SvFieldProps } from '../sv-field/sv-field';
import {
  tagChipStyles,
  tagClearStyles,
  tagRootStyles,
} from './sv-tag-input.styles.ts';

type BaseProps = AutocompleteProps<string, true, boolean, true>;
/** State for the extra textField slot. Native slots receive MUI's ownerState. */
export interface SvTagInputFieldOwnerState extends Omit<
  AutocompleteRenderInputParams,
  'slotProps' | 'size'
> {
  size: NonNullable<BaseProps['size']>;
  readOnly: boolean;
  error: boolean;
}
export interface SvTagInputProps extends Omit<
  BaseProps,
  'renderInput' | 'multiple' | 'freeSolo' | 'options' | 'slotProps' | 'ref'
> {
  ref?: Ref<HTMLDivElement> | undefined;
  label?: ReactNode;
  helperText?: ReactNode;
  error?: boolean;
  placeholder?: string;
  labelAdornment?: SvFieldProps['labelAdornment'];
  options?: readonly string[];
  renderInput?: BaseProps['renderInput'];
  slotProps?: BaseProps['slotProps'] & {
    textField?:
      SvFieldProps | ((ownerState: SvTagInputFieldOwnerState) => SvFieldProps);
  };
}

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvTagInput: SvTagInputProps;
  }
  interface Components {
    SvTagInput?:
      { defaultProps?: Partial<SvTagInputProps> | undefined } | undefined;
  }
}

const ClearContext = createContext<{
  container: () => HTMLSpanElement | null;
  inputRef: RefObject<HTMLInputElement | null>;
  component: NonNullable<BaseProps['slots']>['clearIndicator'];
} | null>(null);

// Keep this adapter stable: a new slot component would remount the focused action.
const HeaderClearIndicator = forwardRef<HTMLButtonElement, IconButtonProps>(
  function HeaderClearIndicator(
    { ownerState, ...props }: IconButtonProps & { ownerState?: unknown },
    ref
  ) {
    const context = useContext(ClearContext);
    if (!context) return null;
    const Component = context.component ?? IconButton;
    return (
      <Portal container={context.container}>
        <Component
          {...props}
          {...(context.component && { ownerState })}
          ref={ref}
          onMouseDown={(event) => {
            props.onMouseDown?.(event);
            // The header is outside MUI's input anchor, so preserve focus here.
            event.preventDefault();
          }}
          onKeyDown={(event) => {
            props.onKeyDown?.(event);
            // Enter/Space activate this button, not Autocomplete's draft input.
            event.stopPropagation();
          }}
          onClick={(event) => {
            props.onClick?.(event);
            if (!event.defaultPrevented)
              context.inputRef.current?.focus({ preventScroll: true });
          }}
        />
      </Portal>
    );
  }
);

export const SvTagInput = forwardRef<HTMLDivElement, SvTagInputProps>(
  function SvTagInput(inProps, ref) {
    const muiDefaults = useDefaultProps<SvTagInputProps>({
      props: {},
      name: 'MuiAutocomplete',
    });
    const svDefaults = useDefaultProps<SvTagInputProps>({
      props: {},
      name: 'SvTagInput',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvTagInput' });
    const resolved = useDefaultProps({
      props: svProps,
      name: 'MuiAutocomplete',
    });
    const {
      label,
      helperText,
      error = false,
      placeholder,
      labelAdornment,
      className,
      sx: _sx,
      slotProps = {},
      slots,
      options = [],
      renderInput,
      renderValue,
      clearIcon,
      clearText = 'Clear',
      size = 'medium',
      ...props
    } = resolved;
    const { textField, ...autocompleteSlots } = slotProps;
    const clearTarget = useRef<HTMLSpanElement>(null);
    const nativeInputRef = useRef<HTMLInputElement>(null);
    const container = useCallback(() => clearTarget.current, []);
    const rootSx = mergeSx(
      !renderInput && tagRootStyles,
      muiDefaults.sx,
      svDefaults.sx,
      inProps.sx
    );

    return (
      <ClearContext.Provider
        value={{
          container,
          inputRef: nativeInputRef,
          component: slots?.clearIndicator,
        }}
      >
        <Autocomplete<string, true, boolean, true>
          {...props}
          onKeyDown={(event) => {
            props.onKeyDown?.(event);
            // Header actions must not commit the draft via MUI's root handler.
            if (
              !renderInput &&
              event.target instanceof Element &&
              event.target.closest('.SvField-header')
            ) {
              event.defaultMuiPrevented = true;
            }
          }}
          ref={ref}
          multiple
          freeSolo
          options={options}
          size={size}
          clearText={clearText}
          clearIcon={
            renderInput
              ? clearIcon
              : clearIcon === undefined
                ? clearText
                : clearIcon
          }
          className={clsx('SvTagInput-root', className)}
          sx={rootSx}
          slots={{
            ...slots,
            chip: slots?.chip ?? SvChip,
            ...(!renderInput && { clearIndicator: HeaderClearIndicator }),
          }}
          slotProps={{
            ...autocompleteSlots,
            root: mergeSlotProps(autocompleteSlots.root, { sx: rootSx }),
            ...(!renderInput && {
              clearIndicator: mergeSlotProps(autocompleteSlots.clearIndicator, {
                tabIndex: 0,
                sx: tagClearStyles,
              }),
            }),
            chip: mergeSlotProps(autocompleteSlots.chip, { sx: tagChipStyles }),
          }}
          renderValue={renderValue}
          renderInput={
            renderInput ??
            ((params) => {
              const fieldProps =
                typeof textField === 'function'
                  ? textField({
                      id: params.id,
                      disabled: params.disabled,
                      fullWidth: params.fullWidth,
                      size,
                      readOnly: props.readOnly ?? false,
                      error,
                    })
                  : textField;
              return (
                <SvField
                  label={label}
                  helperText={helperText}
                  error={error}
                  placeholder={placeholder}
                  labelAdornment={labelAdornment}
                  {...fieldProps}
                  {...params}
                  headerAction={(state) => (
                    <>
                      {typeof fieldProps?.headerAction === 'function'
                        ? fieldProps.headerAction(state)
                        : fieldProps?.headerAction}
                      <Box
                        component="span"
                        ref={clearTarget}
                        className="SvTagInput-clearTarget"
                        sx={{ display: 'flex' }}
                      />
                    </>
                  )}
                  sx={mergeSx(
                    !label &&
                      !fieldProps?.label &&
                      !labelAdornment &&
                      !fieldProps?.labelAdornment &&
                      !fieldProps?.headerAction && {
                        '& .SvField-header:has(.SvTagInput-clearTarget:empty)':
                          { display: 'none' },
                      },
                    fieldProps?.sx
                  )}
                  slotProps={{
                    ...fieldProps?.slotProps,
                    inputLabel: mergeSlotProps(
                      fieldProps?.slotProps?.inputLabel,
                      params.slotProps.inputLabel
                    ),
                    input: (ownerState) => {
                      const slot = fieldProps?.slotProps?.input;
                      const external =
                        typeof slot === 'function' ? slot(ownerState) : slot;
                      return {
                        ...mergeSlotProps(external, params.slotProps.input),
                        ref: composeRefs(
                          external?.ref,
                          params.slotProps.input.ref
                        ),
                      };
                    },
                    htmlInput: (ownerState) => {
                      const slot = fieldProps?.slotProps?.htmlInput;
                      const external =
                        typeof slot === 'function' ? slot(ownerState) : slot;
                      return {
                        ...mergeSlotProps(external, params.slotProps.htmlInput),
                        ref: composeRefs(
                          external?.ref as Ref<HTMLInputElement> | undefined,
                          params.slotProps.htmlInput.ref,
                          nativeInputRef
                        ),
                      };
                    },
                  }}
                />
              );
            })
          }
        />
      </ClearContext.Provider>
    );
  }
);
